/* ---------- Turn the lists above into the shape app.js reads ---------- */

// Clearer names for the two halves of the Earth Shrine map.
const ZONE_LABEL = { 'Earth Shrine — Area 1': 'Earth Shrine — Inside', 'Earth Shrine — Area 2': 'Earth Shrine — Outside' };

// Zone notes and chapter warnings that are about Tablet Shards too.
const SHARD_ZONES = ['Arcane Library', "Fina's Psyche", 'Colosseum'];
const SHARD_CHAPTERS = [5];

// Chapter warnings start with "<b>Title:</b>"; split that into a title and plain text.
function splitAlert(alert) {
  const m = /^<b>(.*?)<\/b>\s*(.*)$/.exec(alert[1]);
  return { kind: alert[0], title: m ? m[1].replace(/:$/, '') : '', text: m ? m[2] : alert[1] };
}
const chestStageNotes = {}, shardStageNotes = {}, shardZoneNotes = {};
Object.keys(CH_ALERTS).forEach(function (c) {
  chestStageNotes[c] = CH_ALERTS[c].map(splitAlert);
  if (SHARD_CHAPTERS.indexOf(+c) >= 0) shardStageNotes[c] = chestStageNotes[c];
});
SHARD_ZONES.forEach(function (z) { shardZoneNotes[z] = ZONE_NOTES[z]; });

/** Fields shared by chests and shards: where it is, how to find it, and whether it's missable. */
function baseItem(r, id) {
  const key = r[6];
  const item = { id: id, num: r[3], stage: r[0], region: r[1], group: ZONE_LABEL[r[2]] || r[2], where: '' };
  if (LOC[key]) {
    item.where = LOC[key][0];
    item.rough = !LOC[key][1];
  }
  if (MISS[key]) item.miss = MISS[key];
  return item;
}

const shardItems = ROWS.filter(function (r) { return r[7] === 's'; }).map(function (r) {
  if (!SHARD_IDS[r[6]]) throw new Error('Tablet Shard ' + r[6] + ' needs a number in SHARD_IDS');
  return baseItem(r, String(SHARD_IDS[r[6]]));
});

const chestItems = ROWS.filter(function (r) { return r[7] === 'c'; }).map(function (r) {
  const item = baseItem(r, r[6]);
  item.name = r[4];
  item.tags = r[5] ? ['Magicite'] : [];
  if (r[2] === 'Oblivion Palace') {
    // The palace safes are the Tablet Shard rewards, in the same order.
    const reward = REWARDS[r[3] - 1];
    item.where = 'Tablet Shard reward: opens once you have handed ' + reward[0] +
      ' shards to the Enigmatic Princess (' + reward[1] + ' Chamber).';
  }
  return item;
});

